const repos=["cloudflare/agents","e2b-dev/E2B","nodejs/undici"];
const out={};
for(const r of repos){const t=await deepwiki.read_wiki_contents({repoName:r});
const lines=t.split("\n");let cur=null,pages=[];
for(const l of lines){if(l.startsWith("# Page: ")){cur={title:l.slice(8),n:0,first:null};pages.push(cur);}else if(cur&&l.startsWith("|")){cur.n++;if(!cur.first)cur.first=l;}}
