const repos=["cloudflare/agents","e2b-dev/E2B","nodejs/undici"];
const out={};
for(const r of repos){const t=await deepwiki.read_wiki_contents({repoName:r});
let title=null,cnt=0,first=null,best={cnt:-1};
const flush=()=>{if(title&&cnt>best.cnt)best={title,cnt,first};};
for(const line of t.split("\n")){if(line.startsWith("# Page: ")){flush();title=line.slice(8);cnt=0;first=null;}
else if(line.startsWith("|")){cnt++;if(!first)first=line;}}
flush();out[r]=best;}
return out;

