const repos=["apify/apify-mcp-server","cloudflare/agents","e2b-dev/E2B","modelcontextprotocol/servers","nodejs/undici","vercel/ai","withastro/astro"];
const res=await Promise.all(repos.map(r=>deepwiki.read_wiki_structure({repoName:r})));
const m={};
res.forEach((t,i)=>{
 const set=new Set();
 t.split("\n").forEach(l=>{const mm=l.match(/^\s*[\d.]+\s+(.*\S)\s*$/);if(mm)set.add(mm[1]);});
 set.forEach(s=>{(m[s]=m[s]||[]).push(repos[i])});
});
return Object.entries(m).filter(([k,v])=>v.length>1).sort((a,b)=>b[1].length-a[1].length).map(([k,v])=>`${k} (${v.length}): ${v.join(", ")}`).join("\n")+"\n---SAMPLE---\n"+res[0].slice(0,300);

